import csv

with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    print('Header:', header)
    print('Number of columns:', len(header))

    # Check a few rows for fields that might need quoting
    for i, row in enumerate(reader):
        if i < 10:
            for j, field in enumerate(row):
                if ',' in field or '"' in field or '\n' in field:
                    print(f'Row {i}, Col {j}: field contains special char: {repr(field)}')
        if i > 20:
            break
    print('Check complete')
EOF
